+import * as http from "http";
+import { claimNext, completeJob, failJob, Job } from "./jobs.ts";
+
+const PORT = process.env.API_PORT ? parseInt(process.env.API_PORT) : 3000;
+
+interface JsonResponse {
+  error?: string;
+  job?: Job;
+}
+
+const sendJson = (res: http.ServerResponse, status: number, data: JsonResponse): void => {
+  res.writeHead(status, { "Content-Type": "application/json" });
+  res.end(JSON.stringify(data));
+};
+
+const parseUrl = (url: string): { pathname: string; query: Record<string, string> } => {
+  const [pathname, queryString] = url.split("?");
+  const query: Record<string, string> = {};
+  if (queryString) {
+    queryString.split("&").forEach((param) => {
+      const [key, value] = param.split("=");
+      query[key] = decodeURIComponent(value);
+    });
+  }
+  return { pathname, query };
+};
+
+export const startApi = (): void => {
+  const server = http.createServer(async (req, res) => {
+    const { pathname } = parseUrl(req.url || "");
+
+    try {
+      if (req.method === "GET" && pathname === "/jobs/next") {
+        const job = await claimNext();
+        if (!job) {
+          return sendJson(res, 204, {});
+        }
+        return sendJson(res, 200, { job });
+      }
+
+      if (req.method === "POST" && pathname.startsWith("/jobs/")) {
+        const parts = pathname.split("/");
+        const jobId = parts[2];
+        const action = parts[3];
+
+        if (action === "complete") {
+          await completeJob(jobId);
+          return sendJson(res, 200, {});
+        }
+
+        if (action === "fail") {
+          await failJob(jobId);
+          return sendJson(res, 200, {});
+        }
+      }
+
+      sendJson(res, 404, { error: "Not found" });
+    } catch (error) {
+      console.error("API error:", error);
+      sendJson(res, 500, { error: "Internal server error" });
+    }
+  });
+
+  server.listen(PORT, () => {
+    console.log(`API server running on port ${PORT}`);
+  });
+};
